/**
 * Intro step (spec/02 §3.23, D101 (5)): the [spot] (128 × 96 dp, ink textMuted, tone border; null = none), the
 * [title] in title (a heading), the [text] in body textMuted (one or two sentences) and „Einführung überspringen“
 * (introSkip) as a text action calling [onSkip]; start-aligned, 8 dp apart, 32 dp above and below, the gutter at the
 * sides. The screen puts SbSteps under its top bar and „Weiter: <Ziel>“ into SbScreen's bottom zone, and centres this
 * in the height between them.
 */
@Composable
fun SbIntroStep(
    title: String,
    text: String,
    onSkip: () -> Unit,
    modifier: Modifier = Modifier,
    spot: ((ink: Color, tone: Color) -> ImageVector)? = SebaroIcons.Spot::Onboarding,
